"""Splitting money between parties."""

from collections.abc import Sequence


def _plain_split(total: int, weights: Sequence[int], indices: list[int]) -> dict[int, int]:
    """Split `total` over `indices` in proportion to their weights, rounding as the README describes."""
    weight_sum = sum(weights[i] for i in indices)
    shares: dict[int, int] = {}
    remainders: dict[int, int] = {}
    for i in indices:
        shares[i], remainders[i] = divmod(total * weights[i], weight_sum)
    leftover = total - sum(shares.values())
    # Remainders are compared as integers over `weight_sum`, so ties are exact.
    by_remainder = sorted(indices, key=lambda i: (-remainders[i], i))
    for i in by_remainder[:leftover]:
        shares[i] += 1
    return shares


def allocate(total: int, weights: Sequence[int], caps: Sequence[int] | None = None) -> list[int]:
    """Split `total` cents in proportion to `weights`. See README.md for the rules."""
    if total < 0:
        raise ValueError("total must not be negative")
    if len(weights) == 0:
        raise ValueError("weights must not be empty")
    if any(w < 0 for w in weights):
        raise ValueError("weights must not be negative")
    if sum(weights) == 0:
        raise ValueError("weights must not all be zero")
    if caps is not None:
        if len(caps) != len(weights):
            raise ValueError("caps must have one entry per weight")
        if any(c < 0 for c in caps):
            raise ValueError("caps must not be negative")
        positive = [i for i, w in enumerate(weights) if w > 0]
        if sum(caps[i] for i in positive) < total:
            raise ValueError("caps of the parties with positive weight cannot hold total")

    result = [0] * len(weights)
    if caps is None:
        for i, share in _plain_split(total, weights, list(range(len(weights)))).items():
            result[i] = share
        return result

    unfixed = list(range(len(weights)))
    remaining = total
    while True:
        active_weight = sum(weights[i] for i in unfixed)
        if remaining == 0 or active_weight == 0:
            break
        shares = _plain_split(remaining, weights, unfixed)
        over = [i for i in unfixed if shares[i] > caps[i]]
        if not over:
            for i in unfixed:
                result[i] = shares[i]
            break
        for i in over:
            result[i] = caps[i]
            remaining -= caps[i]
        unfixed = [i for i in unfixed if i not in over]
    return result
